def can_attend_meetings(intervals):
    sorted_intervals = sorted(intervals, key=lambda pair: pair[0])
    for i in range(1, len(sorted_intervals)):
        if sorted_intervals[i][0] < sorted_intervals[i - 1][1]:
            return False
    return True

